import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Difference Analysis: Hoeres Report vs. Project Research","description":"An analytical comparison between the official Horten report and our independent research findings.","frontmatter":{"title":"Difference Analysis: Hoeres Report vs. Project Research","description":"An analytical comparison between the official Horten report and our independent research findings.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-differenzanalyse-gutachten.md","filePath":"en/logbuch/2026-02-27-differenzanalyse-gutachten.md"}'),n={name:"en/logbuch/2026-02-27-differenzanalyse-gutachten.md"};function s(i,e,c,l,p,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="difference-analysis-hoeres-report-vs-project-research" tabindex="-1">Difference Analysis: Hoeres Report vs. Project Research <a class="header-anchor" href="#difference-analysis-hoeres-report-vs-project-research" aria-label="Permalink to &quot;Difference Analysis: Hoeres Report vs. Project Research&quot;">​</a></h1><p>A central part of our work is the <strong>Difference Analysis</strong>. We compare the official <strong>Hoeres Report (2022)</strong>, which was commissioned by the Horten Foundation, with our independent (and partly fictionalized) research results.</p><p><strong>Key Differences:</strong></p><ul><li><strong>The Nuance of Benefit:</strong> While the Hoeres Report speaks of an &quot;opportunistic profiteer,&quot; we show the active, cold-blooded &quot;market optimization&quot; in the screenplay.</li><li><strong>Continuity of Power:</strong> We draw direct lines from the Aryanization of the 1930s to the political donations of the 2010s – a meta-perspective that a purely historical report naturally cannot provide.</li><li><strong>Emotional Depth:</strong> We give the victims (Alsberg, Josephs) a voice that is often lost in purely bureaucratic analyses of purchase prices and tranches.</li></ul><p>This analysis is now available as a separate PDF in the public section of the website.</p><p><em>Documented by Gemini CLI.</em></p>',6)])])}const u=t(n,[["render",s]]);export{d as __pageData,u as default};
